def call_form():
    form=form_open('call','call')+identity()+'''<label>What were you told in your last review?<textarea name="last-review" rows="3" minlength="10" maxlength="1500" required placeholder="Their exact words, if you remember them."></textarea></label><label>What have you tried so far?<textarea name="tried" rows="3" minlength="5" maxlength="1500" required placeholder="Courses, feedback, working harder, a job search…"></textarea></label><label>If your salary stopped, roughly how many months could your household manage?<select name="runway" required><option value="">Choose a rough range</option><option>Under 3 months</option><option>3 to 6 months</option><option>6 to 12 months</option><option>More than 12 months</option><option>Not sure</option></select></label>'''+optin()+'<button class="d-btn d-full" type="submit">Get a time slot ↗</button>'+form_note()+'</form>'
    return f'''<div class="d-form-card d-call-form"><div data-form-content>{form}</div><div class="d-success" data-form-success hidden tabindex="-1"><span class="d-success-icon">✓</span><h3>Thanks. Now pick a time.</h3><p>Your answers are saved, so we can start with what matters.</p><a class="d-btn d-full" href="{BOOKING}" target="_blank" rel="noopener">Choose a time ↗</a><p class="d-fine">Opens Google Calendar. Check the time zone shown before confirming.</p></div></div>'''

def call():
    return f'''<section class="d-wrap d-section d-call-hero"><div><span class="d-kicker">Free · 20 minutes · Google Meet</span><h1>A real conversation<br>about <em>your next move.</em></h1><p class="d-lede">Bring one situation from work. We’ll work out what is really in the way. If one of my programs would help, I’ll say so. If not, I’ll say that too.</p>{author()}</div><aside class="d-booking-card"><span class="d-kicker">A conversation with Sayantan</span><h2>Let’s look at what’s<br>in the way.</h2><div class="d-booking-details"><span>◷ 20 minutes</span><span>↗ Online on Google Meet</span><span>₹ Free</span></div>{call_form()}<div class="d-booking-divider"></div><p>Want to share some context first?</p><a class="d-text-link" href="{LINKS['coaching']}#fit">Send a short coaching brief ↗</a></aside></section><section class="d-section d-tint"><div class="d-wrap"><div class="d-section-head"><h2>Come as you are.<br>Think about three things.</h2><p>No presentation needed. The short form asks about these three things, so the call starts with what matters.</p></div><div class="d-process"><article><span>01</span><h3>What happened.</h3><p>Your last review or promotion conversation. What were you told, in their exact words?</p></article><article><span>02</span><h3>What you’ve tried.</h3><p>Courses, feedback, working harder, a job search. What happened each time?</p></article><article><span>03</span><h3>Your runway, in months.</h3><p>If your salary stopped, roughly how many months could your household manage? A rough guess is fine.</p></article></div><p class="d-fine">This is a 20-minute diagnosis, not a full coaching session. For an existing purchase or access question, <a href="/help">contact support</a>.</p></div></section>'''

def newsletter():
    form=form_open('newsletter','newsletter')+identity()+'<input type="hidden" name="newsletter-consent" value="yes"><p class="d-fine">By joining, you request The Optional Career and occasional program invitations. Unsubscribe at any time.</p><button class="d-btn d-full" type="submit">Join The Optional Career ↗</button>'+form_note()+'</form>'
    return f'''<section class="d-wrap d-section d-letter-hero"><div><span class="d-kicker">A weekly letter from Sayantan</span><h1>For a career<br>with <em>more choice.</em></h1><p class="d-lede">Leadership, money and the decisions that connect them. One useful idea for your working week.</p><div class="d-letter-preview"><span>THE OPTIONAL CAREER</span><h2>Good work needs<br>a clear explanation.</h2><p>Your update says what you finished. Your manager is trying to understand what changed.</p><p>Before your next update, add one sentence: “Because of this work, ___ is now different.” Start there.</p><small>A sample of the kind of idea you’ll find in the letter.</small></div></div><div><div class="d-form-card"><span class="d-kicker">Join the letter</span><h2>Keep the conversation going.</h2><p>Practical situations, clearer questions and occasional invitations to learn together.</p><div data-form-content>{form}</div><div data-form-success class="d-success" hidden tabindex="-1"><span class="d-success-icon">✓</span><h3>Your request is saved.</h3><p>Your newsletter preference is recorded for review. This demo does not send automated emails.</p></div></div><a class="d-text-link d-letter-read" href="/essays">Read a few essays first ↗</a></div></section>'''

def quiz(key,title,subtitle):
    is_exit=key=='exit';form=form_open('quiz-'+key,'quiz','data-quiz-capture')+identity()+'<input type="hidden" name="test-id" value="'+key+'"><input type="hidden" name="answers"><input type="hidden" name="practice-focus">'+optin()+'<button class="d-btn d-full" type="submit">Show my result ↗</button>'+form_note()+'</form>'
    return f'''<section class="d-wrap d-quiz-hero"><a class="d-back" href="{LINKS['start']}#ladder">← All checks</a><span class="d-kicker">{'Exit Power' if is_exit else 'Earning Power'} · Free · 6 questions</span><h1>{title}</h1><p class="d-lede">{subtitle}</p></section><div class="d-wrap d-quiz-layout" data-demo-quiz="{key}"><aside class="d-quiz-aside"><span class="d-kicker">A useful starting point</span><h3>{'Create room to choose.' if is_exit else 'Practice the next level.'}</h3><p>{'Reflect on what you know about your financial room, commitments and alternatives. No account balances or financial documents needed.' if is_exit else 'Six fictional workplace situations. Choose the response you would actually use, then see the reasoning behind each choice.'}</p><ol><li>Answer six short questions.</li><li>Enter your email to view your result.</li><li>Leave with a practical next step.</li></ol><p class="d-fine">{'A reflection tool, not financial advice or a retirement assessment.' if is_exit else 'A teaching exercise, not a validated assessment or a prediction of promotion.'}</p></aside><div class="d-quiz-workspace"><section data-quiz-intro><span class="d-quiz-big">06<span>small questions.<br>One clearer focus.</span></span><h2>Go with the answer<br>closest to yours.</h2><p>{'There is no ideal life plan to match. Be honest about what you have checked and what still feels uncertain.' if is_exit else 'Use the facts given. Think about your next move in that situation, rather than what sounds most impressive.'}</p><button class="d-btn" data-begin>Let’s begin ↗</button><p class="d-fine">{'About 3–4 minutes' if is_exit else 'About 5–7 minutes'} · Email before results · Newsletter optional</p></section><section data-quiz-questions hidden></section><section data-quiz-gate hidden><span class="d-kicker">All six questions complete</span><h2 tabindex="-1">Your next step<br>is taking shape.</h2><p>Enter your name and email to view your result and practical next step. You can download a copy from the result page.</p>{form}<button class="d-text-link" data-review-answers>← Review my answers</button></section><section data-quiz-report hidden></section></div></div>'''

def build_demo(write):
    pages=[('start-here-blue','Start Here',start(),'start'),('get-coached-blue','Personal Leadership Coaching',coaching(),'coaching'),('philosophy-blue','The Book & Philosophy',philosophy(),'philosophy'),('book-a-call-blue','Book a Free 20-Minute Call',call(),'call'),('newsletter-blue','The Optional Career',newsletter(),'letter')]
    for slug,title,body,active in pages:write('review/'+slug+'.html',shell(title,body,active))
    for key,slug,title,sub in [('judgment','senior-level-judgment','Senior-Level<br><em>Judgment Check.</em>','Move from reporting the problem to making a call.'),('visibility','leadership-visibility','Leadership<br><em>Visibility Check.</em>','Make the contribution behind your work easier to see.'),('exit','exit-power','The <em>Exit Power</em><br>Check.','Understand the room you have to make a different choice.'),('leadership','business-leadership','Business<br><em>Leadership Check.</em>','Own the business outcome, not just the work.')]:
        write('review/tests/'+slug+'.html',shell(re.sub('<[^>]+>','',title.replace('<br>',' ')),quiz(key,title,sub),'start'))
    from home_v2 import home_v2
    write('review/home-v2.html',shell('Start Here (proposed)',home_v2(),'start',extra='<link rel="stylesheet" href="/assets/lib/home-v2.css?v=12"><script type="module" src="/assets/lib/home-v2.js?v=3"></script>'))
    write('review/received-blue.html',shell('Request saved','<section class="d-wrap d-section d-center"><span class="d-kicker">Thank you</span><h1>Your request is saved.</h1><p class="d-lede">This is a review demo. No automated email has been sent.</p><a class="d-btn" href="/review/start-here-blue">Back to Start here ↗</a></section>'))
    # Integrate approved sales demos with the same four-link navigation and footer.
    for kind in ['course','cohort']:
        p=ROOT/f'review/{kind}-blue.html';s=p.read_text()
        s=re.sub(r'<body([^>]*)>',r'<body\1>',s,count=1)
        body_start=s.index('<body');body_end=s.index('>',body_start)+1;main=s.index('<main',body_end)
        s=s[:body_end]+header('learn')+s[main:]
        s=re.sub(r'<footer\b.*?</footer>',footer(),s,count=1,flags=re.S)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/lib/site-demo.css?v=2"><script type="module" src="/assets/lib/site-demo.js?v=2"></script></head>')
        from offer_blocks import cohort_human_block, feedback_example, social_links, compare_section, course_get_block, objections
        s=s.replace('<!--OFFER:human-->',feedback_example()+cohort_human_block()).replace('<!--OFFER:example-->','')
        s=s.replace('</div></div><div class="audience">', '</div>'+social_links()+'</div><div class="audience">')
        s=s.replace('<!--OFFER:compare-cohort-->',compare_section('cohort','#join')).replace('<!--OFFER:objections-cohort-->',objections('cohort'))
        s=s.replace('<!--OFFER:compare-course-->',compare_section('course')).replace('<!--OFFER:course-get-->',course_get_block())
        s=s.replace('https://sayantannandi.com/conversation',LINKS['call'])
        s=s.replace('<span class="invite">Available by invitation</span>', '<a class="btn secondary" href="/review/get-coached-blue">Explore personal coaching ↗</a>')
        s=s.replace('onclick="callDemo()"', 'onclick="location.href=\'/review/book-a-call-blue\'"')
        write(f'review/{kind}-blue.html',s)
